package uz.plugin.easy_pdf_viewer

import android.content.Context
import java.io.IOException
import java.util.concurrent.Executors
import java.util.concurrent.TimeoutException

/**
 * What Dart calls through JNI (bindings in `lib/src/bindings/`, generated by `dart run tool/jnigen.dart`). Only
 * [String]s and primitives cross the boundary; results come back through [ResultCallback], so a call returns at
 * once and rendering runs on a single background thread. Every call answers its callback exactly once.
 */
object EasyPdfViewerApi {
    @Volatile
    private var renderer: PdfRendering? = null

    private val worker = Executors.newSingleThreadExecutor { runnable ->
        Thread(runnable, "easy_pdf_viewer").apply { isDaemon = true }
    }

    internal fun attach(context: Context) {
        renderer = PdfRendering(context.cacheDir)
    }

    internal fun detach() {
        renderer = null
    }

    /** Page count of the PDF at [filePath], as a decimal string. */
    @JvmStatic
    fun getNumberOfPages(filePath: String, clearCacheDir: Boolean, callback: ResultCallback) =
        run(callback) { rendering ->
            if (clearCacheDir) {
                rendering.clearCache()
            }
            rendering.pageCount(filePath).toString()
        }

    /** Renders [pageNumber] (1-based, clamped to the last page) to a PNG and answers its path. */
    @JvmStatic
    fun getPage(filePath: String, pageNumber: Int, callback: ResultCallback) =
        run(callback) { rendering -> rendering.renderPage(filePath, pageNumber) }

    @JvmStatic
    fun clearCacheDir(callback: ResultCallback) = run(callback) { rendering ->
        rendering.clearCache()
        null
    }

    private fun run(callback: ResultCallback, block: (PdfRendering) -> String?) {
        val rendering = renderer
        if (rendering == null) {
            callback.error("NOT_ATTACHED", "The plugin is not attached to an engine", null)
            return
        }
        try {
            worker.execute {
                try {
                    callback.success(block(rendering))
                } catch (t: Throwable) {
                    callback.fail(t)
                }
            }
        } catch (t: Throwable) {
            callback.fail(t)
        }
    }

    private fun ResultCallback.fail(throwable: Throwable) {
        val code = when (throwable) {
            is IllegalArgumentException -> "INVALID_ARGUMENT"
            is IOException -> "IO_ERROR"
            is TimeoutException -> "TIMEOUT"
            is SecurityException -> "UNAUTHORIZED"
            else -> "UNKNOWN"
        }
        error(code, "PDF operation failed", throwable.localizedMessage ?: throwable.toString())
    }
}
